/* ── shared: a domain package declared, its namespace decided, its sections approved, conformance, certified, activated — §PK's ports ── */
const pkr = (s, action, objectId = null, extra = {}) => dom(s, 'intelligence', { action, objectType: 'DPG', objectId, ...extra });
const pkgRow = async (key) => (await q(`select package_id::text id, state, owner_principal_id::text owner from domain.packages where tenant_id = $1 and domain_id = $2 and package_key = $3`, [T, D, key]))[0] ?? null;
const pkgVersion = async (id) => (await q(`select version, semver, state, manifest, certified_by::text certified_by, activated_by::text activated_by, object_version from domain.package_versions where package_id = $1 order by version desc limit 1`, [id]))[0] ?? null;
async function packageCycle({ key, kind, title, manifest, specialist, certifier, label }) {
  let p = await pkgRow(key);
  if (p === null) {
    const r = await call(`${PK}/declare`, pkr(weber, 'domain.package.declare'), { key, kind, title, owner: weber.principalId }, weber.token);
    if (!r.ok) { fail(`J. Weber declares the package ${key}`, r); return null; }
    ok(`J. Weber (strategy owner) DECLARED the ${kind} package ${key} "${title}" → ${r.body.package?.state}`);
    p = await pkgRow(key);
  } else note(`the package ${key} stands (${p.state}) — an earlier run`);
  let v = await pkgVersion(p.id);
  if (v === null || ['withdrawn', 'rejected'].includes(v.state)) {
    const r = await call(`${PK}/${p.id}/versions/propose`, pkr(weber, 'domain.package.version', p.id), { semver: manifest.release.semver, manifest }, weber.token);
    if (!r.ok) { fail(`J. Weber proposes ${key} ${manifest.release.semver}`, r); return null; }
    ok(`J. Weber PROPOSED ${key} v${r.body.version?.version} (${r.body.version?.semver}): DPG object v${r.body.version?.dpg?.object_version ?? r.body.version?.object_version}, manifest ${String(r.body.version?.manifest_digest).slice(0, 12)}…; its certification item ${r.body.version?.item?.state ?? '—'} → [${(r.body.version?.item?.route_roles ?? []).join(', ')}]`);
    v = await pkgVersion(p.id);
  }
  if (v.state === 'proposed') {
    // THE GRAPH'S OWN GATE: the namespace's ontology, proposed by the owner and decided by the ontology steward
    const ns = manifest.ontology_extension.namespace;
    const activeNs = (await q(`select version_id::text, version from graph.ontology_versions where tenant_id = $1 and domain_id = $2 and namespace = $3 and state = 'active'`, [T, D, ns]))[0] ?? null;
    if (activeNs) note(`the ontology of ${ns} v${activeNs.version} is active — an earlier run`);
    else {
      let pend = (await q(`select version_id::text from graph.ontology_versions where tenant_id = $1 and domain_id = $2 and namespace = $3 and state = 'proposed' order by version desc limit 1`, [T, D, ns]))[0]?.version_id ?? null;
      if (pend === null) {
        const types = [...new Set(manifest.ontology_extension.mappings.map((m) => m.maps_to))].sort();
        const r = await call(`${G}/ontology/propose`, dom(weber, 'graph', { action: 'graph.ontology.propose', objectType: 'ONT' }), { namespace: ns, entityTypes: types, predicates: manifest.ontology_extension.predicates,
          rationale: `the ${ns} extension of the ${key} package: ${manifest.ontology_extension.mappings.map((m) => `${m.type} → ${m.maps_to}`).join(', ')} (SYNTHETIC)` }, weber.token);
        if (!r.ok) fail(`J. Weber proposes the ontology of ${ns}`, r); else { pend = r.body.ontology?.version_id ?? null; ok(`J. Weber PROPOSED the ontology of ${ns}: types ${types.join(', ')}; predicates ${manifest.ontology_extension.predicates.map((x) => x.predicate).join(', ')}`); }
      }
      if (pend) {
        const r = await call(`${G}/ontology/${pend}/decide`, dom(steiner, 'graph', { action: 'graph.ontology.decide', objectType: 'ONT', objectId: pend }), { decision: 'approve', reason: `the ${ns} extension maps onto the core types; no core predicate is redefined`, reviews: { compatibility: 'passed', migration: 'passed', domain: 'passed' } }, steiner.token);
        if (!r.ok) fail(`O. Steiner decides the ontology of ${ns}`, r); else ok(`O. Steiner (ontology steward) APPROVED the ontology of ${ns} → active`);
      }
    }
    // THE FIVE SECTIONS, each approved by the named specialist on the digest it read (the proposer's own approval refused)
    const SECTIONS = ['ontology', 'methodology', 'assessment', 'escalation', 'use_boundary'];
    const digestOf = async (section) => (await q(`select domain.dpk_section_digest(manifest, $2) d from domain.package_versions where package_id = $1 and version = $3`, [p.id, section, v.version]))[0].d;
    const decided = async () => q(`select section, decision, approver_principal_id::text by from domain.package_sections where package_id = $1 and version = $2 and decision = 'approved' and expires_at > clock_timestamp()`, [p.id, v.version]);
    if ((await decided()).length === 0) expectRefused(`J. Weber (the proposer, no specialist) approves the ontology section of ${key}`, await call(`${PK}/${p.id}/sections/approve`, pkr(weber, 'domain.package.approve', p.id), { version: v.version, section: 'ontology', digest: await digestOf('ontology'), decision: 'approved', reason: 'the owner approves his own section' }, weber.token), 403);
    for (const section of SECTIONS) {
      if ((await decided()).some((x) => x.section === section)) continue;
      const r = await call(`${PK}/${p.id}/sections/approve`, pkr(specialist, 'domain.package.approve', p.id), { version: v.version, section, digest: await digestOf(section), decision: 'approved', reason: `the ${section} section of ${key} reviewed by the specialist (SYNTHETIC review)`, validDays: 365 }, specialist.token);
      if (!r.ok) fail(`${nm(specialist.principalId)} approves the ${section} section`, r);
    }
    const d = await decided();
    (SECTIONS.every((x) => d.some((y) => y.section === x && y.by === specialist.principalId)) ? ok : bad)(`${nm(specialist.principalId)} (domain specialist) APPROVED the five sections of ${key} v${v.version}: ${d.map((x) => x.section).join(', ')}`);
    // THE CONFORMANCE SUITE (certification), then the certification and the activation
    const run = await call(`${PK}/${p.id}/conformance/run`, pkr(weber, 'domain.package.conformance', p.id), { version: v.version, mode: 'certification' }, weber.token);
    if (!run.ok) fail(`J. Weber runs the conformance suite on ${key}`, run);
    else {
      const checks = run.body.run?.checks ?? [];
      (run.body.run?.passed ? ok : bad)(`J. Weber RAN the conformance suite (certification) on ${key} v${v.version}: ${run.body.run?.passed ? 'PASSED' : 'FAILED'} — ${checks.map((c) => `${c.check} ${c.passed ? '✓' : '✗'}${c.severity === 'advisory' ? ' (advisory)' : ''}`).join(', ')}`);
      for (const c of checks.filter((x) => !x.passed)) note(`  ${c.check} (${c.severity}): ${(c.findings ?? []).join(' | ').slice(0, 400)}`);
    }
    v = await pkgVersion(p.id);
  }
  if (v.state === 'proposed') {
    const r = await call(`${PK}/${p.id}/versions/${v.version}/certify`, pkr(certifier, 'domain.package.certify', p.id), { reason: `every section approved and the suite passed — ${key} v${v.version} certified (SYNTHETIC review)` }, certifier.token);
    if (!r.ok) fail(`${nm(certifier.principalId)} certifies ${key}`, r); else ok(`${nm(certifier.principalId)} (domain specialist, not the proposer) CERTIFIED ${key} v${v.version} → ${r.body.version?.state}`);
    v = await pkgVersion(p.id);
  }
  if (v.state === 'certified') {
    const r = await call(`${PK}/${p.id}/versions/${v.version}/activate`, pkr(weber, 'domain.package.activate', p.id), {}, weber.token);
    if (!r.ok) fail(`J. Weber activates ${key}`, r); else ok(`J. Weber (the owner) ACTIVATED ${key} v${v.version} → ${r.body.version?.state}`);
    v = await pkgVersion(p.id);
  }
  (v.state === 'active' ? ok : bad)(`THE PACKAGE ${key} v${v.version} (${v.semver}) is ${String(v.state).toUpperCase()} — certified by ${nm(v.certified_by)}, activated by ${nm(v.activated_by)}, DPG object v${v.object_version} (${label})`);
  return { id: p.id, version: v.version };
}

